import json, sys
raw = json.loads(sys.stdin.read())
result = json.loads(raw['result'])
data = result['data']
print('data keys:', list(data.keys()))
if 'experiments' in data:
    exps = data['experiments']
    print(f'experiments type: {type(exps).__name__}')
    if isinstance(exps, dict):
        active = {k:v for k,v in exps.items() if isinstance(v, dict) and v.get('status') in ('RUNNING','QUEUED','ALLOCATED','PENDING','PREPARING')}
        print(f'Total: {len(exps)}, Active: {len(active)}')
        for k,v in active.items():
            print(f'  {k}: {v.get(\"status\")}')
        if not active:
            print('No active experiments.')
    elif isinstance(exps, list):
        active = [e for e in exps if isinstance(e, dict) and e.get('status') in ('RUNNING','QUEUED','ALLOCATED','PENDING','PREPARING')]
        print(f'Total: {len(exps)}, Active: {len(active)}')
        if not active:
            print('No active experiments.')
